def q_evaluate_trace(
    env,
    q,
    episodes=100,
    max_steps=1000,
    epsilon=0.0,
    seed=0,
) -> dict:
    """按给定 Q 表做 epsilon 贪心评估，返回逐回合轨迹与成功率。

    env、episodes、max_steps、seed 同名参数的校验与异常分类沿用
    q_learning_trace；epsilon 须为非 bool 的有限 int/float 且在
    [0, 1]，错型抛 TypeError，值错抛 ValueError。q 须为 dict 且键域
    与 q_learning 返回的 Q 相同（从 S 可达的非 G 格与 U/R/D/L 的
    全部组合），值须为有限 float；容器、键型或值型错抛 TypeError，
    键域不符或值非有限抛 ValueError；不修改 q。全部校验先于首次
    reset。

    全部随机性来自一个 random.Random(seed)：每步先取一次 random()，
    小于 epsilon 才再取一次 randrange(4) 按 URDL 选动作，否则取 q
    值最大且 URDL 序首个的动作。每回合 reset，到达 G 即停；到达
    步限截断时保留末步且末步 done=False。

    返回键序为 episodes、success_rate 的 dict：episodes 为回合列表，
    每项为键序 trace、total_reward、success 的 dict；trace 的步结构
    与类型同 q_learning_trace，total_reward 为 int 回报和，success
    仅表示到达 G；success_rate 为成功数除以回合数的 float。相同
    参数与 seed 逐值一致。仅用标准库，不引入命令行入口。
    """
    if not isinstance(env, GridWorld):
        raise TypeError("env must be a GridWorld")
    if isinstance(episodes, bool) or not isinstance(episodes, int):
        raise TypeError("episodes must be an int")
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise TypeError("seed must be an int")
    if isinstance(max_steps, bool) or not isinstance(max_steps, int):
        raise TypeError("max_steps must be an int")
    if isinstance(epsilon, bool) or not isinstance(epsilon, (int, float)):
        raise TypeError("epsilon must be an int or float")
    if not isinstance(q, dict):
        raise TypeError("q must be a dict")
    for key, value in q.items():
        if (
            not isinstance(key, tuple)
            or len(key) != 2
            or not isinstance(key[0], tuple)
            or len(key[0]) != 2
            or any(isinstance(v, bool) or not isinstance(v, int) for v in key[0])
            or not isinstance(key[1], str)
        ):
            raise TypeError("q keys must be ((row, col), action) tuples")
        if isinstance(value, bool) or not isinstance(value, float):
            raise TypeError("q values must be floats")
    if episodes <= 0:
        raise ValueError("episodes must be positive")
    if max_steps <= 0:
        raise ValueError("max_steps must be positive")
    if not _is_finite_number(epsilon) or epsilon < 0 or epsilon > 1:
        raise ValueError("epsilon must be finite and in [0, 1]")
    actions = tuple(_ACTIONS)  # U, R, D, L
    expected_keys = {
        (state, action)
        for state in _reachable_cells(env)
        if env._cell(state) != "G"
        for action in actions
    }
    if set(q) != expected_keys:
        raise ValueError("q must cover exactly the q_learning key domain")
    for value in q.values():
        if not math.isfinite(value):
            raise ValueError("q values must be finite")

    rng = random.Random(seed)

    episode_records = []
    successes = 0
    for _ in range(episodes):
        state = env.reset()
        trace = []
        total_reward = 0
        success = False
        for _ in range(max_steps):
            r, c = state
            if rng.random() < epsilon:
                action = actions[rng.randrange(4)]
            else:
                action = max(actions, key=lambda a: q[(state, a)])
            next_state, reward, done = env.step(action)
            next_r, next_c = next_state
            trace.append(
                [r, c, action, next_r, next_c, reward, done]
            )
            total_reward += reward
            if done:
                success = True
                break
            state = next_state
        if success:
            successes += 1
        episode_records.append(
            {
                "trace": trace,
                "total_reward": total_reward,
                "success": success,
            }
        )
    return {
        "episodes": episode_records,
        "success_rate": successes / episodes,
    }


